async function checkDefault() {
  const url = 'https://huggingface.co/api/models/distilbert-base-uncased-finetuned-sst-2-english';
  try {
    const response = await fetch(url);
    const data = await response.json();
    return data;
  } catch (e) {
    return e.message;
  }
}
checkDefault().then(data => JSON.stringify(data).substring(0, 500));

async function fetchAndSearch() {
  const url = 'https://raw.githubusercontent.com/huggingface/transformers/v4.46.0/src/transformers/pipelines/__init__.py';
  try {
    const response = await fetch(url);
    const text = await response.text();
    // Find text-classification section
    const idx = text.indexOf('"text-classification"');
    if (idx >= 0) {
      // Get 2000 characters around the match
      const start = Math.max(0, idx - 200);
      const end = Math.min(text.length, idx + 2000);
      return text.substring(start, end);
    }
    return 'NOT FOUND';
  } catch (e) {
    return 'ERROR: ' + e.message;
  }
}
fetchAndSearch();

async function fetchAndSearch() {
  const url = 'https://raw.githubusercontent.com/huggingface/transformers/v4.46.0/src/transformers/pipelines/__init__.py';
  const result = await fetch(url);
  const text = await result.text();

  // Find text-classification section
  const idx = text.indexOf('"text-classification"');
  let found = '';
  if (idx >= 0) {
    const start = Math.max(0, idx - 200);
    const end = Math.min(text.length, idx + 2000);
    found = text.substring(start, end);
  } else {
    found = 'NOT FOUND';
  }

  // Write to page
  const div = document.createElement('div');
  div.id = 'extracted-content';
  div.textContent = found;
  document.body.appendChild(div);
  return found.length;
}
fetchAndSearch();
